/**
 * An event input that carries who provides its subject (`tool.describe`,
 * `command.describe`, `agent.offer`, `agent.spawn`), read for its tier.
 *
 * Typed loosely on purpose: a missing or odd provider fails closed.
 */
export type Provided = {
  readonly provider?: { readonly tier?: unknown } | null
}

import type { TargetTier } from 'x-coder'

/**
 * What the shared hook needs of `next` on those events: the call, and the
 * continuation past the user tier.
 */
export type ProvidedNext<E, R> = {
  (e: E): Promise<R>

  /**
   * Continues the dispatch at `tier`, the links between skipped (Next's).
   */
  readonly to: (e: E, tier: TargetTier) => Promise<R>
}

